#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200200;
const int INF = 1e9;

int n, ANS = INF;
int crr[MAXN], dist[MAXN], res[MAXN];
bool clr[MAXN];
vector<int> gr[MAXN];

void init() {
	ANS = INF;
	for (int v = 0; v < n; ++v)
		gr[v].clear();
	fill(dist, dist + n, INF);
	memset(clr, 0, n);
}

void dfs(int v, int p) {
	if (dist[v] >= ANS) return;
	if (clr[v]) ANS = min(ANS, dist[v]);
	for (int u: gr[v]) {
		if (u == p) continue;
		if (dist[v] + 1 < dist[u]) {
			dist[u] = dist[v] + 1;
			dfs(u, v);
		} else ANS = min(ANS, dist[v] + 1 + dist[u]);
	}
}

void solve() {
	dist[*crr] = 0;
	dfs(*crr, -1);
	clr[*crr] = true;
	for (int i = 1; i < n; ++i) {
		dist[crr[i]] = 0;
		dfs(crr[i], -1);
		clr[crr[i]] = true;
		res[i] = ANS;
	}
}

int main() {
	int gorilla; cin >> gorilla;
	while (gorilla--) {
		cin >> n >> *crr, --(*crr);
		init();
		for (int i = 1; i < n; ++i)
			cin >> crr[i], --crr[i];
		for (int i = 1; i < n; ++i) {
			int v, u; cin >> v >> u, --v, --u;
			gr[v].push_back(u);
			gr[u].push_back(v);
		}
		solve();
		for (int i = 1; i < n; ++i)
			cout << res[i] << ' ';
		cout << '\n';
	}
}

#include<bits/stdc++.h>

using namespace std;

void solve()
{
    int n;
    cin >> n;
    vector<int> token(n), boni(n);
    vector<vector<int>> g(n);
    vector<int> good(n);
    int m;
    cin >> m;
    int p, b;
    cin >> p >> b;
    for(int i = 0; i < p; i++)
    {
        int x;
        cin >> x;
        --x;
        token[x] = 1;
    }
    for(int i = 0; i < b; i++)
    {
        int x;
        cin >> x;
        --x;
        boni[x] = 1;
    }
    for(int i = 0; i < m; i++)
    {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    for(int i = 0; i < n; i++)
        for(auto x : g[i])
            if(boni[i] && boni[x]) good[i] = 1;
    set<int> good_tokens;
    set<int> not_so_good_tokens;
    for(int i = 0; i < n; i++)
        for(auto x : g[i])
        {
            if(token[i] && good[x]) good_tokens.insert(i);
            else if(token[i] && boni[x]) not_so_good_tokens.insert(i);
        }
    vector<int> d(n, int(1e9));
    queue<int> q;
    d[0] = 0;
    q.push(0);
    while(!q.empty())
    {
        int k = q.front();
        q.pop();
        for(auto x : g[k])
        {
            if(d[x] > d[k] + 1)
            {
                d[x] = d[k] + 1;
                if(boni[x]) q.push(x);
            }
        }
    }
    bool has_ans = false;
    for(int i = 0; i < n; i++)
    {
        if(!token[i] || d[i] > n) continue;
        has_ans |= (!good_tokens.empty() && (*good_tokens.begin() != i || *good_tokens.rbegin() != i));
        int cnt = not_so_good_tokens.size();
        if(not_so_good_tokens.count(i)) cnt--;
        has_ans |= d[i] <= 1 + cnt;
    }
    cout << (has_ans ? "YES" : "NO") << endl;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
#endif
    int tc = 1;
    cin >> tc;
    for(int i = 0; i < tc; i++)
    {
        solve();
    }
}
